import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';
import { apiLayThongBao } from '../../api/goi_api';

const QuanLyThongBaoCuDan = () => {
    const [notifications, setNotifications] = useState([]);
    const [loading, setLoading] = useState(true);

    const user = JSON.parse(localStorage.getItem('user') || '{}');

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const res = await apiLayThongBao();
                setNotifications(res.data || []);
            } catch (error) {
                console.error('Lỗi lấy thông báo:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    if (loading) {
        return (
            <div style={{ ...containerStyle, justifyContent: 'center', alignItems: 'center' }}>
                <div style={{ color: '#fff', fontSize: '18px' }}>Đang tải thông báo...</div>
            </div>
        );
    }

    return (
        <div style={containerStyle} className="glass-card">
            <div style={headerStyle}>
                <div>
                    <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>📢 THÔNG BÁO TÒA NHÀ</h2>
                    <p style={{ color: 'rgba(255,255,255,0.7)', margin: '5px 0 0 0', fontSize: '12px' }}>
                        Dữ liệu đã được đồng bộ hệ thống
                    </p>
                </div>

                {user?.so_phong && <div style={roomTagHeader}>Phòng: {user.so_phong}</div>}
            </div>

            <div style={{ flex: 1, padding: '20px', overflow: 'hidden' }}>
                <div className="custom-scrollbar" style={scrollContainerStyle}>
                    {notifications.length > 0 ? (
                        notifications.map((noti) => (
                            <div key={noti.id} style={notiCardStyle}>
                                <div style={notiHeaderRow}>
                                    <span style={{ ...roomTagStyle, backgroundColor: '#333' }}>
                                        CHUNG
                                    </span>
                                    <span style={dateStyle}>
                                        {new Date(noti.ngay_gui).toLocaleString('vi-VN')}
                                    </span>
                                </div>

                                <h3 style={titleStyle}>{noti.tieu_de}</h3>
                                <p style={bodyStyle}>{noti.noi_dung}</p>

                                <div style={{ marginTop: '8px', fontSize: '12px', color: '#777', fontStyle: 'italic' }}>
                                    Người gửi: {noti.nguoi_gui || 'ad'}
                                </div>
                            </div>
                        ))
                    ) : (
                        <div style={emptyStateStyle}>Hiện tại không có thông báo nào.</div>
                    )}
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.2); border-radius: 10px; }
            `}</style>
        </div>
    );
};

const containerStyle = {
    flex: 1,
    borderRadius: '30px',
    display: 'flex',
    flexDirection: 'column',
    backgroundImage: `url(${chatBgImg})`,
    backgroundSize: 'cover',
    height: 'calc(100vh - 120px)',
    overflow: 'hidden'
};

const headerStyle = {
    padding: '20px 30px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    background: 'rgba(0,0,0,0.3)',
    borderBottom: '1px solid rgba(255,255,255,0.1)'
};

const roomTagHeader = {
    backgroundColor: 'rgba(139, 94, 94, 0.8)',
    color: '#fff',
    padding: '6px 15px',
    borderRadius: '12px',
    fontSize: '14px',
    fontWeight: 'bold'
};

const scrollContainerStyle = {
    height: '100%',
    overflowY: 'auto',
    display: 'flex',
    flexDirection: 'column',
    gap: '15px'
};

const notiCardStyle = {
    backgroundColor: 'rgba(255,255,255,0.95)',
    padding: '18px',
    borderRadius: '20px',
    boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
};

const notiHeaderRow = {
    display: 'flex',
    justifyContent: 'space-between',
    marginBottom: '10px'
};

const roomTagStyle = {
    color: '#fff',
    padding: '3px 10px',
    borderRadius: '6px',
    fontSize: '10px',
    fontWeight: 'bold'
};

const dateStyle = {
    fontSize: '11px',
    color: '#aaa'
};

const titleStyle = {
    margin: '0 0 8px 0',
    fontSize: '17px',
    color: '#222'
};

const bodyStyle = {
    margin: 0,
    fontSize: '14px',
    color: '#555',
    lineHeight: '1.5',
    whiteSpace: 'pre-wrap'
};

const emptyStateStyle = {
    textAlign: 'center',
    color: '#fff',
    marginTop: '100px',
    opacity: 0.8
};

export default QuanLyThongBaoCuDan;
